begin
 select role into role_name from portal_private.accounts where user_id=auth.uid() and is_active;
 if role_name is null or role_name not in ('ADMIN','CEO','EMPLOYEE') then raise exception 'Operational staff only' using errcode='42501'; end if;
 if request_id is null or jsonb_typeof(payload) is distinct from 'object'
 or jsonb_typeof(payload->'kind') is distinct from 'string' or jsonb_typeof(payload->'date') is distinct from 'string'
 or jsonb_typeof(payload->'values') is distinct from 'object'
 or exists(select 1 from jsonb_object_keys(payload) p where p not in ('kind','date','values','override'))
 then raise exception 'Invalid document' using errcode='22023'; end if;
 k=payload->>'kind'; spec=defs->k; v=payload->'values';
 if spec is null or payload->>'date' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid kind/date' using errcode='22023'; end if;
 begin d=(payload->>'date')::date; exception when others then raise exception 'Invalid date' using errcode='22023'; end;
 y=extract(year from d);
 if y not between 1900 and 2200 or to_char(d,'YYYY-MM-DD')<>payload->>'date' then raise exception 'Invalid year' using errcode='22023'; end if;
 if exists(select 1 from jsonb_each(v) e where not spec ? e.key or jsonb_typeof(e.value)<>'string') then raise exception 'Unknown field' using errcode='22023'; end if;
 for entry in select * from jsonb_each(spec) loop
  value=coalesce(v->>entry.key,'');
  if length(value)>(entry.value->>'max')::integer or (entry.value->>'required')::boolean and length(trim(value))=0 then raise exception 'Invalid field length/required' using errcode='22023'; end if;
  if value='' then continue; end if;
  if entry.value->>'type'='money' and value !~ '^\d{1,8}(\.\d{1,2})?$' then raise exception 'Invalid amount' using errcode='22023'; end if;
  if entry.value->>'type'='count' and value !~ '^\d{1,7}$' then raise exception 'Invalid count' using errcode='22023'; end if;
  if entry.value ? 'options' and not (entry.value->'options') ? value then raise exception 'Invalid choice' using errcode='22023'; end if;
  if entry.value->>'type'='date' then
   if value !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid field date' using errcode='22023'; end if;
   begin d=value::date; exception when others then raise exception 'Invalid field date' using errcode='22023'; end;
   if extract(year from d) not between 1900 and 2200 or to_char(d,'YYYY-MM-DD')<>value then raise exception 'Invalid field date' using errcode='22023'; end if;
  end if;
 end loop;
 if coalesce(v->>'start','')<>'' and coalesce(v->>'end','')<>'' and v->>'end'<v->>'start' or coalesce(v->>'from','')<>'' and coalesce(v->>'to','')<>'' and v->>'to'<v->>'from' then raise exception 'Invalid period' using errcode='22023'; end if;
 if k='KC-L' and coalesce(v->>'rent','')<>'' and exists(select 1 from jsonb_each_text(v) e where e.key ~ '^installment\.[0-3]\.amount$' and e.value<>'') then
  select coalesce(sum(nullif(e.value,'')::numeric),0) into amount_sum from jsonb_each_text(v) e where e.key ~ '^installment\.[0-3]\.amount$';
  if amount_sum<>(v->>'rent')::numeric then raise exception 'Rent installments mismatch' using errcode='22023'; end if;
 end if;
 if k='KC-M' and (v->>'brokerShare')::numeric>100 then raise exception 'Invalid broker share' using errcode='22023'; end if;
 if k='KC-B' and (coalesce(nullif(v->>'percentage',''),'0')::numeric>100 or coalesce(nullif(v->>'percentage',''),'0')::numeric>0 and coalesce(nullif(v->>'fixedFee',''),'0')::numeric>0) then raise exception 'Invalid commission' using errcode='22023'; end if;
 if k='KB' then
  select coalesce(sum(nullif(e.value,'')::numeric),0) into amount_sum from jsonb_each_text(v) e where e.key ~ '^expense\.[0-2]\.amount$';
  if coalesce(nullif(v->>'trustPaid',''),'0')::numeric>amount_sum then raise exception 'Trust payments exceed expenses' using errcode='22023'; end if;
 end if;
 if payload ? 'override' then
  if role_name not in ('ADMIN','CEO') then raise exception 'Executive required' using errcode='42501'; end if;
  num=payload->>'override';
  if jsonb_typeof(payload->'override') is distinct from 'string' or num !~ ('^'||k||'-'||y::text||'-[0-9]{5,9}$') then raise exception 'Invalid number' using errcode='22023'; end if;
  seq=substring(num from '([0-9]+)$')::bigint;
  if seq<1 then raise exception 'Invalid sequence' using errcode='22023'; end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(request_id::text,0));
 select * into saved from portal_private.bill_forms where id=request_id;
 if found then
  if saved.actor<>auth.uid() then raise exception 'Request not accessible' using errcode='42501'; end if;
  if saved.snapshot->'form'<>payload or saved.snapshot->>'templateVersion'<>'2' then raise exception 'Retry payload changed' using errcode='22023'; end if;
  return jsonb_build_object('number',saved.number,'form',saved.snapshot->'form','createdAt',saved.created_at);
 end if;
 if payload ? 'override' then
  insert into portal_private.bill_counters values(k,y,seq) on conflict(kind,year) do update set last_value=greatest(portal_private.bill_counters.last_value,excluded.last_value);
 else
  insert into portal_private.bill_counters values(k,y,1) on conflict(kind,year) do update set last_value=portal_private.bill_counters.last_value+1 returning last_value into seq;
  num=k||'-'||y::text||'-'||case when seq<100000 then lpad(seq::text,5,'0') else seq::text end;
 end if;
 insert into portal_private.bill_forms(id,actor,number,snapshot) values(request_id,auth.uid(),num,jsonb_build_object('form',payload,'templateVersion',2)) returning * into saved;
 return jsonb_build_object('number',saved.number,'form',payload,'createdAt',saved.created_at);
end $$;
revoke all on function public.issue_standard_form(uuid,jsonb) from public,anon;
grant execute on function public.issue_standard_form(uuid,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;

